 @Override public boolean dispatchTouchEvent(MotionEvent e){int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){workspaceTouchX=e.getRawX();workspaceTouchY=e.getRawY();notificationSwipe=false;singleSwipe=true;hiddenOpened=false;hiddenGesture=false;}if(action==MotionEvent.ACTION_POINTER_DOWN)singleSwipe=false;if(notificationSwipe){if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL)notificationSwipe=false;return true;}if(action==MotionEvent.ACTION_MOVE&&singleSwipe&&e.getPointerCount()==1&&dragging==null&&!editing&&Math.abs(e.getRawX()-workspaceTouchX)<dp(50)&&e.getRawY()-workspaceTouchY>dp(80)){notificationSwipe=true;MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();openNotificationShade();return true;}if(hiddenOpened){if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL)hiddenOpened=false;return true;}if(action==MotionEvent.ACTION_POINTER_DOWN&&e.getPointerCount()==2&&dragging==null){hiddenGesture=true;hiddenStartY=(e.getY(0)+e.getY(1))/2;hiddenStartX=(e.getX(0)+e.getX(1))/2;}if(hiddenGesture&&action==MotionEvent.ACTION_MOVE&&e.getPointerCount()==2){float y=(e.getY(0)+e.getY(1))/2,x=(e.getX(0)+e.getX(1))/2;if(hiddenStartY-y>dp(72)&&Math.abs(x-hiddenStartX)<dp(100)){hiddenGesture=false;hiddenOpened=true;MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();startActivity(new Intent(this,HiddenGateActivity.class).putExtra("quick",true));return true;}}if(action==MotionEvent.ACTION_POINTER_UP||action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL)hiddenGesture=false;return super.dispatchTouchEvent(e);}
