 public boolean dispatchDragEvent(DragEvent e){if(dragging==null)return false;int action=e.getAction();if(action==DragEvent.ACTION_DRAG_STARTED)return true;if(action==DragEvent.ACTION_DRAG_LOCATION){int dir=e.getX()<dp(28)?-1:e.getX()>getWidth()-dp(28)?1:0;if(dir!=edge){edge=dir;handler.removeCallbacks(edgeTurn);if(dir!=0)handler.postDelayed(edgeTurn,550);}Workspace grid=(Workspace)getChildAt(page);int cw=Math.max(1,(getWidth()-dp(24))/columns);int col=Math.max(0,Math.min(columns-1,(int)(e.getX()-dp(12))/cw));int row=Math.max(0,Math.min(rows-1,(int)e.getY()/grid.cellHeight()));hover=LayoutMetrics.slot(page,capacity(),row,col,columns);for(int i=0;i<getChildCount();i++)getChildAt(i).invalidate();return true;}if(action==DragEvent.ACTION_DRAG_EXITED){edge=0;hover=-1;handler.removeCallbacks(edgeTurn);return true;}if(action==DragEvent.ACTION_DROP){Workspace targetGrid=(Workspace)getChildAt(page);if(targetGrid==null)return false;int cellWidth=Math.max(1,(getWidth()-dp(24))/columns);int targetCol=Math.max(0,Math.min(columns-1,(int)(e.getX()-dp(12))/cellWidth));int targetRow=Math.max(0,Math.min(rows-1,(int)e.getY()/targetGrid.cellHeight()));hover=LayoutMetrics.slot(page,capacity(),targetRow,targetCol,columns);int from=-1;for(int i=0;i<apps.size();i++)if(apps.get(i).id.equals(dragging))from=i;if(from>=0&&hover>=0){model.move(dragging,hover);save();}return true;}if(action==DragEvent.ACTION_DRAG_ENDED){if(source!=null)source.setAlpha(1);dragging=null;source=null;hover=-1;edge=0;handler.removeCallbacks(edgeTurn);post(()->render());return true;}return true;}
