 public boolean dispatchDragEvent(DragEvent e){int action=e.getAction();if(action==DragEvent.ACTION_DRAG_ENDED){target=-1;invalidate();return true;}if(dragging==null||!appMap.containsKey(dragging))return false;if(action==DragEvent.ACTION_DRAG_STARTED)return true;if(action==DragEvent.ACTION_DRAG_ENTERED||action==DragEvent.ACTION_DRAG_LOCATION){handler.removeCallbacks(edgeTurn);edge=0;hover=-1;target=targetAt(e.getX());invalidate();return true;}if(action==DragEvent.ACTION_DRAG_EXITED){target=-1;invalidate();return true;}if(action==DragEvent.ACTION_DROP){ArrayList<String> ids=DockRules.place(dockIds(),dragging,targetAt(e.getX()),dockCount);prefs.edit().putString("dock_v3",android.text.TextUtils.join("\n",ids)).apply();target=-1;post(()->render());return true;}return true;}
